import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.Cm6XCzck.js";const h=JSON.parse('{"title":"9. Three-Valued Governance Interpretation","description":"","frontmatter":{},"headers":[],"relativePath":"en/publications/implementation-case-i0.6/part-03.md","filePath":"en/publications/implementation-case-i0.6/part-03.md","lastUpdated":1786111154000}'),o={name:"en/publications/implementation-case-i0.6/part-03.md"};function r(c,e,d,l,s,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="_9-three-valued-governance-interpretation" tabindex="-1">9. Three-Valued Governance Interpretation <a class="header-anchor" href="#_9-three-valued-governance-interpretation" aria-label="Permalink to &quot;9. Three-Valued Governance Interpretation&quot;">​</a></h1><p>TMPA separates semantic judgment from view classification:</p><table tabindex="0"><thead><tr><th>Judgment</th><th>Typical view</th><th>Meaning</th></tr></thead><tbody><tr><td><code>valid</code></td><td>authoritative</td><td>Required evidence and applicable rules establish the conclusion.</td></tr><tr><td><code>invalid</code></td><td>quarantined / rejected</td><td>A deterministic violation excludes the affected evidence or action.</td></tr><tr><td><code>undetermined</code></td><td>partial / disputed / pending_human</td><td>Required evidence is missing, conflicting, or awaiting authorized human decision.</td></tr></tbody></table><p>FCoP and CodeFlowMu already expose many source facts needed by this model, but I0.6 does not claim that either product emits the complete S0.5 canonical graph, issue set, judgment, and view for every criterion. Reference Reader PASS establishes an executable interpretation; product verdicts describe the current projection and execution gap.</p><h1 id="_10-reproducibility-and-evidence-quality" tabindex="-1">10. Reproducibility and Evidence Quality <a class="header-anchor" href="#_10-reproducibility-and-evidence-quality" aria-label="Permalink to &quot;10. Reproducibility and Evidence Quality&quot;">​</a></h1><p>The V2 archive contains 125 ZIP entries and 122 payload hashes. Its archive CRC, payload SHA-256 manifest, 45 JSON files, relevant JSONL, strict UTF-8 decoding after documented normalization, filename safety, absolute-path scan, and credential scan pass. All V1/V2 raw log files are byte-identical; V2 changes only summaries, matrix language, validation metadata, and the explicit encoding boundary.</p><p>The strongest reproducible statements are:</p><ul><li>the S0.5 Reference Reader produced 14/14 PASS on its fixed synthetic fixtures;</li><li>the listed FCoP and CodeFlowMu test counts and failures are preserved in raw logs;</li><li>WP-13 V3 passed its internal package validation;</li><li>the C01–C14 product matrix follows the declared strict rule that one failed mandatory assertion prevents PASS.</li></ul><p>The package is author-produced local evidence. It is not signed, independently timestamped, independently rerun, or a stable public CodeFlowMu release snapshot.</p><h1 id="_11-limitations" tabindex="-1">11. Limitations <a class="header-anchor" href="#_11-limitations" aria-label="Permalink to &quot;11. Limitations&quot;">​</a></h1><ol><li>FCoP and CodeFlowMu are maintained by project participants; this creates author and implementation bias.</li><li>The CodeFlowMu source worktree was dirty and local-only, despite isolated execution.</li><li>C08, C11, and C12 lack exact product execution.</li><li>C01, C03–C06, C09, C10, and C13 lack complete canonical product output.</li><li>C02 and C07 retain executed failures.</li><li>XiaoDian AI had no fixed S0.5 package and was NOT RUN.</li><li>No evidence establishes representative SME performance, adoption cost, comparison baselines, broad fault recovery, Byzantine resilience, or third-party adoption.</li><li>U+FFFD characters in two normalized FCoP logs limit byte-level forensic claims.</li></ol><h1 id="_12-engineering-roadmap" tabindex="-1">12. Engineering Roadmap <a class="header-anchor" href="#_12-engineering-roadmap" aria-label="Permalink to &quot;12. Engineering Roadmap&quot;">​</a></h1><ol><li>Close FCoP <code>parent</code> persistence/readback and release-surface snapshots, then rerun the full v3.2.5-equivalent suite.</li><li>Adjudicate the CodeFlowMu <code>ADMIN/PM</code> prompt contract, implement the approved product-or-test change, and rerun the complete Runtime suite.</li><li>Publish a retrievable clean CodeFlowMu candidate or reproduction snapshot.</li><li>Implement maintained FCoP and CodeFlowMu S0.5 projection adapters.</li><li>Execute C08, C11, and C12 and complete canonical outputs for all PARTIAL criteria.</li><li>Establish a fixed XiaoDian evidence package before making new S0.5 claims.</li><li>Obtain independent reruns and preserve all deviations.</li></ol><h1 id="_13-engineering-conclusion" tabindex="-1">13. Engineering Conclusion <a class="header-anchor" href="#_13-engineering-conclusion" aria-label="Permalink to &quot;13. Engineering Conclusion&quot;">​</a></h1><p>I0.6 advances the Implementation Case from the historical S0.4 baseline to a fresh S0.5 author-run evidence baseline. The result is intentionally mixed: the Reference Reader passes all 14 synthetic criteria, while product evidence contains one PASS, eight PARTIAL, three NOT RUN, and two FAIL. This is stronger and more informative than a success-only demonstration because it identifies specific implementation and projection gaps without weakening the normative contract.</p><p>FCoP remains the protocol layer; its packages are the reference implementation. CodeFlowMu remains the downstream application. WP-13 supplies a bounded multi-agent governance case showing that persistent evidence and separated roles can contain an unverified completion claim. None of these engineering observations proves the TMPA theory, full product conformance, or independent adoption.</p><h1 id="artifact-availability" tabindex="-1">Artifact Availability <a class="header-anchor" href="#artifact-availability" aria-label="Permalink to &quot;Artifact Availability&quot;">​</a></h1><p>The complete V2 evidence archive is available at <a href="/joinwell52/evidence/tmpa/i0.6/tmpa-i0.6-local-evidence-20260806-v2.zip">tmpa-i0.6-local-evidence-20260806-v2.zip</a>, SHA-256 <code>c55cb41fb90f63216fafe6e5b552f4917e56910d120d3b51486f96eba066c2d0</code>. Reviewable matrix, test-summary, source-inventory, validation, and redaction metadata are stored under <a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/conformance/tmpa-core-s0.5/external-runs/20260806-local-evidence-v2" target="_blank" rel="noreferrer"><code>research/conformance/tmpa-core-s0.5/external-runs/20260806-local-evidence-v2</code></a>.</p><p>The historical S0.4 corpus remains at <a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/conformance/tmpa-core-s0.4" target="_blank" rel="noreferrer"><code>research/conformance/tmpa-core-s0.4</code></a>. WP-13 V3 remains at <code>/evidence/tmpa/i0.5/</code>. Git history is the publication version history; no separate paper archive has editorial authority.</p><h1 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h1><p>[1] TMPA Project. “TMPA Core Specification S0.5.” GitHub, 2026.</p><p>[2] TMPA Project. “TMPA Architecture Paper A0.7.” GitHub, 2026.</p><p>[3] FCoP Project. “FCoP — File-based Coordination Protocol,” tag v3.2.5, commit <code>b3dc23439c6aaa6a6b3765655b87e5924e0257f9</code>. GitHub, 2026.</p><p>[4] CodeFlowMu Project. Local isolated evidence snapshot based on commit <code>c4ebc146cb8ef0409a4c9eb571a8f2432ade3bd0</code>, version <code>0.3.0-alpha</code>, captured 2026-08-07.</p><p>[5] CodeFlowMu Project. “WP-13 Multi-Agent Fact-Check Publication Evidence V3,” commit <code>609571ddb22d1fbb2bfb5e54692c07beeef4cf23</code>, 2026.</p><p>[6] TMPA Project. “I0.6 Local Engineering Evidence V2,” package <code>tmpa-i0.6-local-evidence-20260806-v2</code>, 2026.</p>',26)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
